// The shell's texts: English is the source, Italian the first translation (app_*.arb,
// generated by gen-l10n). Each component resolves the system languages the embedder passes
// (`FlutterEngineUpdateLocales`) against the supported ones, falling back to English.

import 'dart:ui' show PlatformDispatcher;

import 'package:flutter/widgets.dart';
import 'package:flutter_localizations/flutter_localizations.dart';

import 'app_localizations.dart';

export 'app_localizations.dart';

/// The English texts, for widgets shown without a `Localizations` above (tests, previews).
final AppLocalizations englishTexts = lookupAppLocalizations(
  const Locale('en'),
);

/// The texts for `context`: the resolved language, or English.
AppLocalizations l10nOf(BuildContext context) =>
    AppLocalizations.of(context) ?? englishTexts;

/// The first preferred language the shell supports (language code match), or English.
Locale resolveLocale(List<Locale> preferred) {
  for (final locale in preferred) {
    for (final supported in AppLocalizations.supportedLocales) {
      if (supported.languageCode == locale.languageCode) return supported;
    }
  }
  return const Locale('en');
}

/// The language code of the system's first supported language (for `.desktop` names).
String systemLanguage() =>
    resolveLocale(PlatformDispatcher.instance.locales).languageCode;

/// Puts the shell's texts under `child`, following the system languages (also when they
/// change).
class ShellLocalizations extends StatefulWidget {
  const ShellLocalizations({super.key, required this.child, this.locales});

  final Widget child;

  /// The preferred languages; null: those of the platform.
  final List<Locale>? locales;

  @override
  State<ShellLocalizations> createState() => _ShellLocalizationsState();
}

class _ShellLocalizationsState extends State<ShellLocalizations>
    with WidgetsBindingObserver {
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeLocales(List<Locale>? locales) => setState(() {});

  @override
  Widget build(BuildContext context) => Localizations(
    locale: resolveLocale(
      widget.locales ?? PlatformDispatcher.instance.locales,
    ),
    delegates: const [
      AppLocalizations.delegate,
      GlobalWidgetsLocalizations.delegate,
    ],
    child: widget.child,
  );
}
